def get_route_template(request: Request) -> str:
    for route in request.app.routes:
        if hasattr(route, "path"):
            match, _ = route.matches({"type": "http", "path": request.url.path, "method": request.method, "query_string": b""})
            from starlette.routing import Match
            if match == Match.FULL:
                return route.path
    return "unmatched"

def get_now(x_test_clock=None):
    if TEST_CLOCK_ENABLED and x_test_clock:
        try:
            return datetime.fromisoformat(x_test_clock.replace("Z","+00:00")).astimezone(UTC)
        except:
            raise HTTPException(status_code=422,detail={"error":{"code":"invalid_clock","message":"Bad X-Test-Clock"}})
    return datetime.now(UTC)

def is_business(dt):
    local = dt.astimezone(WARSAW)
    if local.weekday() >= 5:
        return False
    h = local.hour + local.minute/60 + local.second/3600
    return 8 <= h < 16

def next_business_open(dt):
    local = dt.astimezone(WARSAW)
    if local.weekday() < 5:
        today_open = local.replace(hour=8,minute=0,second=0,microsecond=0)
        if local < today_open:
            return today_open.astimezone(UTC)
    candidate = local.replace(hour=8,minute=0,second=0,microsecond=0)
    days = 1
    while True:
        candidate = candidate + timedelta(days=days)
        days = 1
        if candidate.weekday() < 5:
            return candidate.astimezone(UTC)

def add_business_hours(start, delta):
    remaining = delta.total_seconds()
    current = start.astimezone(WARSAW)
    if not is_business(current.astimezone(UTC)):
        current = next_business_open(current.astimezone(UTC)).astimezone(WARSAW)
    while remaining > 0:
        day_close = current.replace(hour=16,minute=0,second=0,microsecond=0)
        available = (day_close - current).total_seconds()
        if available <= 0:
            current = next_business_open(current.astimezone(UTC)).astimezone(WARSAW)
            continue
        if remaining <= available:
            return (current + timedelta(seconds=remaining)).astimezone(UTC)
        remaining -= available
        current = next_business_open(current.astimezone(UTC)).astimezone(WARSAW)
    return current.astimezone(UTC)

def compute_sla(priority, created_at):
    ack_d, res_d = SLA_TARGETS[priority]
    if priority == "P1" and C1 == "wallclock":
        return created_at + ack_d, created_at + res_d
    return add_business_hours(created_at, ack_d), add_business_hours(created_at, res_d)

def fmt(dt):
    if dt is None: return None
    return dt.astimezone(UTC).strftime("%Y-%m-%dT%H:%M:%SZ")

def to_dict(t):
    return {k: t.get(k) for k in ["id","title","description","reporter","impact","urgency","priority","state","created_at","acknowledged_at","resolved_at","closed_at","related_to","sla"]}

# ---------- DORA helpers ----------

def parse_dt(s: str) -> datetime:
    return datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(UTC)

def round_half_up(x) -> int:
    return int(decimal.Decimal(str(x)).quantize(decimal.Decimal('1'), rounding=decimal.ROUND_HALF_UP))

def round_ratio(x) -> float:
    q = decimal.Decimal('0.000001')
    return float(decimal.Decimal(str(x)).quantize(q, rounding=decimal.ROUND_HALF_UP))

def median_seconds(values):
    if not values:
        return None
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return round_half_up((s[n // 2 - 1] + s[n // 2]) / 2)

def compute_metrics(window_from: datetime, window_to: datetime, events: list) -> dict:
    seen_ids = set()
    deduped = []
    for e in events:
        if e["event_id"] not in seen_ids:
            seen_ids.add(e["event_id"])
            deduped.append(e)

    commits = {e["sha"]: e for e in deduped if e["type"] == "commit"}
    all_deployments = [e for e in deduped if e["type"] == "deployment"]
    incidents_list = [e for e in deduped if e["type"] == "incident"]

    prod_deps = [
        d for d in all_deployments
        if d["environment"] == "production"
        and window_from <= parse_dt(d["at"]) < window_to
    ]

    memo = {}
    def resolve_change(sha):
        if sha in memo:
            return memo[sha]
        c = commits.get(sha)
        if c is None:
            memo[sha] = None
            return None
        if c["reverts"] is None:
            memo[sha] = c["change_id"]
            return c["change_id"]
        result = resolve_change(c["reverts"])
        memo[sha] = result
        return result

    for sha in commits:
        resolve_change(sha)

    change_first_commit = {}
    for sha, c in commits.items():
        cid = memo.get(sha)
        if cid is None:
            continue
        at = parse_dt(c["at"])
        if cid not in change_first_commit or at < change_first_commit[cid]:
            change_first_commit[cid] = at

    succ_deps = sorted(
        [d for d in prod_deps if d["outcome"] == "success"],
        key=lambda d: parse_dt(d["at"])
    )
    seen_sha_dep = set()
    lead_time_pairs = []
    negative_count = 0

    for d in succ_deps:
        dep_at = parse_dt(d["at"])
        for sha in d.get("commits", []):
            if sha in seen_sha_dep:
                continue
            seen_sha_dep.add(sha)
            c = commits.get(sha)
            if c is None:
                continue
            diff = (dep_at - parse_dt(c["at"])).total_seconds()
            if diff < 0:
                negative_count += 1
                diff = 0
            lead_time_pairs.append(round_half_up(diff))

    prod_dep_shas = set()
    for d in prod_deps:
        for sha in d.get("commits", []):
            prod_dep_shas.add(sha)
    never_main = sum(1 for sha in prod_dep_shas if commits.get(sha, {}).get("branch") != "main")
    no_commits_count = sum(1 for d in prod_deps if not d.get("commits"))
    revert_chains = sum(1 for c in commits.values() if c.get("reverts") is not None)

    inc_opened = {}
    inc_resolved = {}
    inc_deployments = {}
    for i in incidents_list:
        iid = i["incident_id"]
        if i["phase"] == "opened":
            inc_opened[iid] = parse_dt(i["at"])
            inc_deployments[iid] = i.get("deployments", [])
        elif i["phase"] == "resolved":
            inc_resolved[iid] = parse_dt(i["at"])

    failed_deps = [d for d in prod_deps if d["outcome"] == "failure"]
    recovery_times = []
    open_failures = 0
    recovered_failures = 0

    for d in failed_deps:
        dep_id = d["deployment_id"]
        dep_at = parse_dt(d["at"])
        covering = None
        for iid, deps in inc_deployments.items():
            if dep_id in deps and iid in inc_opened:
                if covering is None:
                    covering = iid
                elif inc_opened[iid] < inc_opened[covering]:
                    covering = iid
                elif inc_opened[iid] == inc_opened[covering] and iid < covering:
                    covering = iid
        if covering is None or covering not in inc_resolved:
            open_failures += 1
        else:
            recovered_failures += 1
            diff = (inc_resolved[covering] - dep_at).total_seconds()
            if diff < 0:
                diff = 0
            recovery_times.append(round_half_up(diff))

    intervals = []
    for iid in inc_opened:
        start = inc_opened[iid]
        end = inc_resolved.get(iid, window_to)
        intervals.append((iid, start, end))
    overlapping_pairs = 0
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            a_open, a_end = intervals[i][1], intervals[i][2]
            b_open, b_end = intervals[j][1], intervals[j][2]
            if a_open < b_end and b_open < a_end:
                overlapping_pairs += 1

    window_days = (window_to - window_from).total_seconds() / 86400
    dep_freq = round_ratio(len(prod_deps) / window_days) if prod_deps else 0.0
    cfr = round_ratio(len(failed_deps) / len(prod_deps)) if prod_deps else None
    rework_deps = [d for d in prod_deps if d.get("unplanned") and d.get("caused_by")]
    drr = round_ratio(len(rework_deps) / len(prod_deps)) if prod_deps else None

    changes_delivered = set()
    for d in succ_deps:
        dep_at = parse_dt(d["at"])
        if not (window_from <= dep_at < window_to):
            continue
        for sha in d.get("commits", []):
            cid = memo.get(sha)
            if cid:
                changes_delivered.add(cid)

    change_first_succ_dep = {}
    for d in sorted(succ_deps, key=lambda x: parse_dt(x["at"])):
        dep_at = parse_dt(d["at"])
        if not (window_from <= dep_at < window_to):
            continue
        for sha in d.get("commits", []):
            cid = memo.get(sha)
            if cid and cid in changes_delivered and cid not in change_first_succ_dep:
                change_first_succ_dep[cid] = dep_at

    true_lt = []
    for cid in changes_delivered:
        if cid not in change_first_succ_dep or cid not in change_first_commit:
            continue
        diff = (change_first_succ_dep[cid] - change_first_commit[cid]).total_seconds()
        if diff < 0:
            diff = 0
        true_lt.append(round_half_up(diff))

    all_changes = set(v for v in memo.values() if v is not None)

    return {
        "spec_version": "1.0.0",
        "window": {
            "from": window_from.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "to": window_to.strftime("%Y-%m-%dT%H:%M:%SZ"),
        },
        "deployment_frequency_per_day": dep_freq,
        "change_lead_time_seconds_p50": median_seconds(lead_time_pairs),
        "failed_deployment_recovery_time_seconds_p50": median_seconds(recovery_times),
        "change_fail_rate": cfr,
        "deployment_rework_rate": drr,
        "counts": {
            "deployments": len(prod_deps),
            "successful_deployments": len(succ_deps),
            "failed_deployments": len(failed_deps),
            "recovered_failures": recovered_failures,
            "open_failures": open_failures,
            "rework_deployments": len(rework_deps),
            "lead_time_pairs": len(lead_time_pairs),
            "changes": len(all_changes),
        },
        "anomalies": {
            "negative_lead_time_pairs": negative_count,
            "deployments_without_commits": no_commits_count,
            "commits_never_on_main": never_main,
            "revert_chains_collapsed": revert_chains,
            "overlapping_incident_pairs": overlapping_pairs,
        },
        "ground_truth": {
            "changes_delivered": len(changes_delivered),
            "true_change_lead_time_seconds_p50": median_seconds(true_lt),
        },
    }

def err422(msg):
    return JSONResponse(status_code=422, content={"error": {"code": "validation", "message": msg}})

# ---------- app ----------

app = FastAPI()

@app.middleware("http")
async def record_metrics(request: Request, call_next):
    start = time.perf_counter()
    response = await call_next(request)
    duration = time.perf_counter() - start
    # Get route template - must be done after routing
    route_template = "unmatched"
    for route in request.app.routes:
        if hasattr(route, "path") and hasattr(route, "methods"):
            from starlette.routing import Match
            match, _ = route.matches({"type": "http", "path": request.url.path, "method": request.method, "query_string": b""})
            if match == Match.FULL:
                route_template = route.path
                break
    REQUEST_DURATION.labels(
        http_request_method=request.method,
        http_route=route_template,
        http_response_status_code=str(response.status_code),
    ).observe(duration)
    return response

@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError):
    return JSONResponse(status_code=422, content={"error": {"code": "validation", "message": str(exc.errors()[0]["msg"])}})

@app.exception_handler(404)
async def h404(req, exc):
    return JSONResponse(status_code=404, content={"error":{"code":"not_found","message":"Not found"}})

@app.get("/health")
def health():
    return {"status":"ok","service":"svcdesk"}

@app.get("/metrics")
def metrics():
    data = generate_latest(REGISTRY)
    return Response(content=data, media_type=CONTENT_TYPE_LATEST)

@app.get("/kb/search")
async def kb_search(q: Optional[str] = None):
    if q is None or len(q) < 1 or len(q) > 200:
        return JSONResponse(status_code=422, content={"error": {"code": "validation", "message": "q must be 1-200 characters"}})
    try:
        async with httpx.AsyncClient(timeout=3.0) as client:
            resp = await client.get(f"{KB_INDEX_URL}/search", params={"q": q})
            if resp.status_code == 503:
                return JSONResponse(status_code=502, content={"error": {"code": "upstream_unavailable", "message": "kb-index unavailable"}})
            return Response(content=resp.content, status_code=resp.status_code, media_type=resp.headers.get("content-type", "application/json"))
    except Exception:
        return JSONResponse(status_code=502, content={"error": {"code": "upstream_unavailable", "message": "kb-index unavailable"}})

class Reporter(BaseModel):
    name: str
    email: Optional[str] = None
    vip: bool = False
    @field_validator("name")
    @classmethod
    def vn(cls,v):
        if not 1<=len(v)<=100: raise ValueError("name 1-100")
        return v

class TicketCreate(BaseModel):
    title: str
    description: Optional[str] = ""
    reporter: Reporter
    impact: int
    urgency: int
    related_to: Optional[str] = None
    @field_validator("title")
    @classmethod
    def vt(cls,v):
        if not 1<=len(v)<=200: raise ValueError("title 1-200")
        return v
    @field_validator("description")
    @classmethod
    def vd(cls,v):
        if v and len(v)>4000: raise ValueError("desc max 4000")
        return v or ""
    @field_validator("impact","urgency")
    @classmethod
    def vr(cls,v):
        if v not in (1,2,3): raise ValueError("must be 1-3")
        return v

@app.post("/tickets", status_code=201)
def create_ticket(body: TicketCreate, x_test_clock: Optional[str]=Header(default=None)):
    now = get_now(x_test_clock)
    pri = PRIORITY_MATRIX[(body.impact,body.urgency)]
    if C3=="vip" and body.reporter.vip and pri in ("P3","P4"):
        pri = "P2"
    ack_due, res_due = compute_sla(pri, now)
    tid = str(uuid.uuid4())
    t = {"id":tid,"title":body.title,"description":body.description,"reporter":body.reporter.model_dump(),"impact":body.impact,"urgency":body.urgency,"priority":pri,"state":"new","created_at":fmt(now),"acknowledged_at":None,"resolved_at":None,"closed_at":None,"related_to":body.related_to,"sla":{"ack_due_at":fmt(ack_due),"resolve_due_at":fmt(res_due)}}
    tickets_db[tid] = t
    save_tickets(tickets_db)
    return to_dict(t)

@app.get("/tickets")
def list_tickets(state: Optional[str]=None, priority: Optional[str]=None):
    r = list(tickets_db.values())
    if state: r=[t for t in r if t["state"]==state]
    if priority: r=[t for t in r if t["priority"]==priority]
    return [to_dict(t) for t in r]

@app.get("/tickets/{tid}")
def get_ticket(tid: str):
    if tid not in tickets_db:
        raise HTTPException(status_code=404,detail={"error":{"code":"not_found","message":"Not found"}})
    return to_dict(tickets_db[tid])

@app.get("/tickets/{tid}/sla")
def get_sla(tid: str, x_test_clock: Optional[str]=Header(default=None)):
    if tid not in tickets_db:
        raise HTTPException(status_code=404,detail={"error":{"code":"not_found","message":"Not found"}})
    t = tickets_db[tid]
    now = get_now(x_test_clock)
    ack_due = datetime.fromisoformat(t["sla"]["ack_due_at"].replace("Z","+00:00"))
    res_due = datetime.fromisoformat(t["sla"]["resolve_due_at"].replace("Z","+00:00"))
    ack_at = t.get("acknowledged_at")
    res_at = t.get("resolved_at")
    ack_b = datetime.fromisoformat(ack_at.replace("Z","+00:00"))>ack_due if ack_at else now>ack_due
    res_b = datetime.fromisoformat(res_at.replace("Z","+00:00"))>res_due if res_at else now>res_due
    is_biz = not (t["priority"]=="P1" and C1=="wallclock")
    paused = t["state"] not in ("resolved","closed") and is_biz and not is_business(now)
    return {"priority":t["priority"],"ack_due_at":t["sla"]["ack_due_at"],"resolve_due_at":t["sla"]["resolve_due_at"],"ack_breached":ack_b,"resolve_breached":res_b,"paused":paused}

def transition(tid, from_states, to, clock, field=None):
    if tid not in tickets_db:
        raise HTTPException(status_code=404,detail={"error":{"code":"not_found","message":"Not found"}})
    t = tickets_db[tid]
    if t["state"] not in from_states:
        raise HTTPException(status_code=409,detail={"error":{"code":"invalid_transition","message":f"Cannot go from {t['state']}"}})
    now = get_now(clock)
    t["state"] = to
    if field: t[field] = fmt(now)
    save_tickets(tickets_db)
    return to_dict(t)

@app.post("/tickets/{tid}/ack")
def ack(tid: str, x_test_clock: Optional[str]=Header(default=None)):
    return transition(tid,["new"],"acknowledged",x_test_clock,"acknowledged_at")

@app.post("/tickets/{tid}/start")
def start(tid: str, x_test_clock: Optional[str]=Header(default=None)):
    return transition(tid,["acknowledged"],"in_progress",x_test_clock)

@app.post("/tickets/{tid}/resolve")
def resolve(tid: str, x_test_clock: Optional[str]=Header(default=None)):
    return transition(tid,["in_progress"],"resolved",x_test_clock,"resolved_at")

@app.post("/tickets/{tid}/close")
def close_t(tid: str, x_test_clock: Optional[str]=Header(default=None)):
    return transition(tid,["resolved"],"closed",x_test_clock,"closed_at")

@app.post("/tickets/{tid}/reopen")
def reopen(tid: str, x_test_clock: Optional[str]=Header(default=None)):
    if tid not in tickets_db:
        raise HTTPException(status_code=404,detail={"error":{"code":"not_found","message":"Not found"}})
    t = tickets_db[tid]
    now = get_now(x_test_clock)
    state = t["state"]
    if state == "closed":
        if C2 == "immutable":
            raise HTTPException(status_code=409,detail={"error":{"code":"ticket_closed","message":"Closed tickets cannot be reopened"}})
        closed_at = datetime.fromisoformat(t["closed_at"].replace("Z","+00:00"))
        if now > closed_at + timedelta(days=7):
            raise HTTPException(status_code=409,detail={"error":{"code":"reopen_window_expired","message":"Window expired"}})
    elif state == "resolved":
        resolved_at = datetime.fromisoformat(t["resolved_at"].replace("Z","+00:00"))
        if now > resolved_at + timedelta(days=7):
            raise HTTPException(status_code=409,detail={"error":{"code":"reopen_window_expired","message":"Window expired"}})
    else:
        raise HTTPException(status_code=409,detail={"error":{"code":"invalid_transition","message":f"Cannot reopen from {state}"}})
    t["state"]="in_progress"
    t["resolved_at"]=None
    t["closed_at"]=None
    save_tickets(tickets_db)
    return to_dict(t)

