@app.post("/dora/metrics")
async def dora_metrics(request: Request):
    try:
        body = await request.json()
    except:
        return err422("body must be valid JSON")

    if not isinstance(body, dict):
        return err422("body must be an object")
    if "window" not in body:
        return err422("window is required")
    if "events" not in body or not isinstance(body["events"], list):
        return err422("events must be an array")

    w = body.get("window", {})
    if not isinstance(w, dict) or "from" not in w or "to" not in w:
        return err422("window must have from and to")

    try:
        wf = parse_dt(w["from"])
    except:
        return err422("window.from must be RFC 3339")
    try:
        wt = parse_dt(w["to"])
    except:
        return err422("window.to must be RFC 3339")

    if wt <= wf:
        return err422("window.to must be after window.from")

    events = body["events"]
    shas = set()
    dep_ids = set()

    for e in events:
        if not isinstance(e, dict):
            return err422("each event must be an object")
        if "event_id" not in e or "type" not in e or "at" not in e:
            return err422("event missing required fields")
        try:
            parse_dt(e["at"])
        except:
            return err422("event.at must be RFC 3339")
        if e["type"] == "commit":
            if "sha" not in e:
                return err422("commit missing sha")
            shas.add(e["sha"])
            has_reverts = e.get("reverts") is not None
            has_change_id = e.get("change_id") is not None
            if has_reverts == has_change_id:
                return err422("commit must have change_id xor reverts")
        elif e["type"] == "deployment":
            if "deployment_id" not in e:
                return err422("deployment missing deployment_id")
            dep_ids.add(e["deployment_id"])
        elif e["type"] == "incident":
            if "incident_id" not in e or "phase" not in e:
                return err422("incident missing required fields")

    for e in events:
        if e["type"] == "commit" and e.get("reverts") and e["reverts"] not in shas:
            return err422(f"reverts references unknown sha {e['reverts']}")
        if e["type"] == "deployment":
            for sha in e.get("commits", []):
                if sha not in shas:
                    return err422(f"deployment commits references unknown sha {sha}")
        if e["type"] == "incident":
            for dep_id in e.get("deployments", []):
                if dep_id not in dep_ids:
                    return err422(f"incident references unknown deployment {dep_id}")

    return compute_metrics(wf, wt, events)

@app.get("/dora/ticket-events")
def ticket_events():
    result = []
    phase_map = [
        ("created_at", "created", "new"),
        ("acknowledged_at", "acknowledged", "acknowledged"),
        ("resolved_at", "resolved", "resolved"),
        ("closed_at", "closed", "closed"),
    ]
    for t in tickets_db.values():
        for field, phase, state in phase_map:
            ts = t.get(field)
            if ts:
                result.append({
                    "ticket_id": t["id"],
                    "at": ts,
                    "phase": phase,
                    "priority": t["priority"],
                    "state": state,
                })
    result.sort(key=lambda x: (x["at"], x["ticket_id"]))
    return result